sys_script.script:
(function executeFlow1(current, previous) {
    if (current.u_status == 'submitted') {
        var checkFields = ['u_temp_check', 'u_cleaning_check', 'u_hygiene_check', 'u_pest_check', 'u_expiry_check', 'u_storage_check', 'u_equip_check'];
        var hasFailure = false;
        for (var i = 0; i < checkFields.length; i++) {
            if (current.getValue(checkFields[i]) == 'fail') { hasFailure = true; break; }
        }
        if (hasFailure) {
            current.u_status = 'failed';
            current.u_risk_level = 'critical';
            var grIss = new GlideRecord('x_fresh_guard_360_issue');
            grIss.initialize();
            grIss.setValue('u_issue_title', 'Daily Checklist Failure at Store');
            grIss.setValue('u_store', current.u_store);
            grIss.setValue('u_department', current.u_department);
            grIss.setValue('u_risk_level', 'high');
            grIss.setValue('u_capa_required', true);
            grIss.setValue('u_status', 'open');
            grIss.insert();
            gs.info('[FLOW 1] Created Food Safety Issue for Failed Checklist');
        } else {
            current.u_status = 'completed';
            gs.info('[FLOW 1] Checklist Passed - Status set to Completed');
        }
    }
})(current, previous);
